import{_ as i,c as o,a6 as r,o as t}from"./chunks/framework.CsOMnFVz.js";const a="/assets/image-20260619101411708.rvG-ay-T.png",s="/assets/image-20260619103053448.C__7H0Mo.png",n="/assets/image-20260619113753231.DvfRno6s.png",g=JSON.parse('{"title":"Linux Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/linux/commands.md","filePath":"en/linux/commands.md"}'),d={name:"en/linux/commands.md"};function c(l,e,h,p,m,u){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="linux-commands" tabindex="-1">Linux Commands <a class="header-anchor" href="#linux-commands" aria-label="Permalink to &quot;Linux Commands&quot;">​</a></h1><h2 id="user-configuration" tabindex="-1">User Configuration <a class="header-anchor" href="#user-configuration" aria-label="Permalink to &quot;User Configuration&quot;">​</a></h2><ul><li>Superuser (root): the command prompt is <strong>#</strong>; can do anything on a Linux system without restrictions</li><li>Normal user: the command prompt is <strong>$</strong>; operations on the Linux system are restricted</li></ul><p>On a fresh system, the root user has no password. Use <code>sudo passwd root</code> to set a password for the root user.</p><p><code>sudo</code> privilege escalation: when used, the identity changes from a normal user -&gt; root</p><p>Switch user: <code>su 【username】</code>; if no username is given, it switches to the root user by default.</p><p>Exit the root user: <code>exit</code></p><p><img src="'+a+'" alt="image-20260619101411708"></p><h3 id="adding-a-user" tabindex="-1">Adding a User <a class="header-anchor" href="#adding-a-user" aria-label="Permalink to &quot;Adding a User&quot;">​</a></h3><p><code>sudo useradd -m user1 -s /bin/bash</code></p><p>The system will create a directory named user1 under the directory &quot;/home&quot;.</p><ul><li><code>-m</code> create the home directory</li><li><code>-s</code> specify the shell to use (bash is the most popular shell in the industry)</li></ul><h3 id="configuring-a-password" tabindex="-1">Configuring a Password <a class="header-anchor" href="#configuring-a-password" aria-label="Permalink to &quot;Configuring a Password&quot;">​</a></h3><p><code>sudo passwd user1</code></p><p>Once the password is set, user1 can log in to the server with their own username and password.</p><h3 id="deleting-a-user" tabindex="-1">Deleting a User <a class="header-anchor" href="#deleting-a-user" aria-label="Permalink to &quot;Deleting a User&quot;">​</a></h3><p><code>sudo userdel -r user1</code></p><p><img src="'+s+'" alt="image-20260619103053448"></p><h2 id="directory-and-file-operations" tabindex="-1">Directory and File Operations <a class="header-anchor" href="#directory-and-file-operations" aria-label="Permalink to &quot;Directory and File Operations&quot;">​</a></h2><h3 id="viewing-files-and-directories" tabindex="-1">Viewing Files and Directories <a class="header-anchor" href="#viewing-files-and-directories" aria-label="Permalink to &quot;Viewing Files and Directories&quot;">​</a></h3><p><code>ls</code> lists all sub-files and sub-directories in the specified directory</p><p><code>ls -a</code> shows all sub-directories and files in the specified directory (including hidden files, e.g. those starting with a dot)</p><p><code>ls -l</code> lists detailed information for all directories and files in the specified directory</p><p><code>ls -l /home/wilson</code> — the details shown on each line are, in order:</p><p>File type and permissions Number of hard links File owner File group File size Last modified time File name</p><p>Linux does not distinguish file types by extension. The 9 characters at the end represent the file&#39;s access permissions, grouped into 3 groups of 3 bits each.</p><p>The first group represents the creator&#39;s permissions, the second group the permissions of users in the same group, and the third group the permissions of other users. The three characters in each group represent read, write, and execute permissions on the file, respectively.</p><p>The permissions are: r (read), w (write), x (execute), - (no permission). Each group can be represented by a number, e.g. r-x:5, rw-:6, r--:4, so the three groups can be represented by three numbers, e.g. rwxr-xr-x:755, rw-r--r--:644.</p><h3 id="changing-the-working-directory" tabindex="-1">Changing the Working Directory <a class="header-anchor" href="#changing-the-working-directory" aria-label="Permalink to &quot;Changing the Working Directory&quot;">​</a></h3><p><code>cd</code> changes the working directory</p><p><code>cd ~</code> switches to your own working directory /home/wilson</p><p><code>cd /</code> switches to the root directory</p><p><code>cd -</code> switches to the previous directory</p><p><code>. </code> represents the current directory</p><h3 id="viewing-the-current-working-directory" tabindex="-1">Viewing the Current Working Directory <a class="header-anchor" href="#viewing-the-current-working-directory" aria-label="Permalink to &quot;Viewing the Current Working Directory&quot;">​</a></h3><p><code>pwd</code> shows the current directory</p><h3 id="creating-and-deleting-directories" tabindex="-1">Creating and Deleting Directories <a class="header-anchor" href="#creating-and-deleting-directories" aria-label="Permalink to &quot;Creating and Deleting Directories&quot;">​</a></h3><p><code>mkdir dir</code> creates a folder named dir; if you use <code>sudo mkdir</code>, the creator of the folder is root</p><p><code>rmdir</code> deletes files — as long as you have delete permission on the current file or folder, you can delete it, regardless of who owns the file</p><p><code>rm -r</code> deletes a folder</p><p><code>rm -r *</code> deletes all files in a folder</p><p><code>rm -rf</code> deletes all files in a folder without any confirmation prompt</p><h3 id="copying-files-and-directories" tabindex="-1">Copying Files and Directories <a class="header-anchor" href="#copying-files-and-directories" aria-label="Permalink to &quot;Copying Files and Directories&quot;">​</a></h3><p><code>cp file1 file2</code> copies the specified source file to the target file, or copies multiple source files to the target directory</p><p><code>cp -i file1 day/</code> copies file1 to the day folder; if a file with the same name already exists, you will be prompted</p><p><code>cp -r /home/wilson /home/wilson1</code> to copy a directory; this copies the sub-directories and files inside it as well, and the target must also be a directory</p><h3 id="moving-files" tabindex="-1">Moving Files <a class="header-anchor" href="#moving-files" aria-label="Permalink to &quot;Moving Files&quot;">​</a></h3><p><code>mv /home/file1 .</code> moves file1 from the home folder to the current directory</p><h3 id="showing-the-directory-structure" tabindex="-1">Showing the Directory Structure <a class="header-anchor" href="#showing-the-directory-structure" aria-label="Permalink to &quot;Showing the Directory Structure&quot;">​</a></h3><p><img src="'+n+'" alt="image-20260619113753231"></p><h3 id="changing-directory-or-file-permissions" tabindex="-1">Changing Directory or File Permissions <a class="header-anchor" href="#changing-directory-or-file-permissions" aria-label="Permalink to &quot;Changing Directory or File Permissions&quot;">​</a></h3><p><code>chmod</code> controls access permissions for files or directories</p><p><strong>Numeric method</strong></p><p>First understand what the numeric attributes mean: 0 means no permission, 1 means execute permission, 2 means write permission, 4 means read permission, and then add them up. So the numeric attribute format should be three octal numbers from 0 to 7, in the order (u)(g)(o). For example, if you want the owner of a file to have both &quot;read/write&quot; permissions, you add 4 (read) + 2 (write) = 6 (read/write).</p><p>For example: after running <code>chmod 644 hello.txt</code> you get <code>-rw-r--r-- 1 wilson wilson 6 Jun 18</code></p><p><code>22:47 hello.txt</code></p><ul><li>The file owner (wilson) has read and write permissions</li><li>Users in the same group as the owner have read permission</li><li>Other users have read permission</li></ul><h3 id="finding-files" tabindex="-1">Finding Files <a class="header-anchor" href="#finding-files" aria-label="Permalink to &quot;Finding Files&quot;">​</a></h3><p>The find search criteria can be a compound condition made up of the logical operators not, and, or.</p><ul><li>and: logical AND, represented by <code>-a</code> in commands; the search condition is satisfied only when all given conditions are met</li><li>or: logical OR, represented by <code>-o</code> in commands; the search condition is satisfied as long as any one of the given conditions is met</li><li>not: logical NOT, represented by <code>!</code> in commands; finds files that do not satisfy the given conditions</li></ul><p>Common search criteria</p><ul><li><p><code>-empty</code> find files with a size of 0 or empty directories</p></li><li><p><code>-perm</code> find files and directories with the specified permissions; permissions can be expressed like 711, 644</p></li><li><p><code>-mmin n</code> find all files whose content was modified n minutes ago</p><p><code>find . -mmin -60</code> find files modified in the past 60 minutes</p></li><li><p><code>-mtime n</code> find all files whose content was modified n days ago</p></li><li><p><code>-xargs</code> execute the given Linux command on the matching files without asking the user whether to run it</p><p><code>find . -empty|xargs rm -rf</code> find all empty files and empty folders and delete them</p></li><li><p><code>-size</code> find files of the specified size; + means larger than, - means smaller than</p><p><code>find . -size +10M</code> find all files larger than 10M</p></li></ul><h3 id="listing-overall-disk-space-usage-of-the-file-system" tabindex="-1">Listing Overall Disk Space Usage of the File System <a class="header-anchor" href="#listing-overall-disk-space-usage-of-the-file-system" aria-label="Permalink to &quot;Listing Overall Disk Space Usage of the File System&quot;">​</a></h3><p><code>df -h</code></p><h3 id="showing-disk-usage-of-each-file-and-directory" tabindex="-1">Showing Disk Usage of Each File and Directory <a class="header-anchor" href="#showing-disk-usage-of-each-file-and-directory" aria-label="Permalink to &quot;Showing Disk Usage of Each File and Directory&quot;">​</a></h3><p><code>du -h</code></p><p><code>--max-depth=0</code> controls the depth, i.e. how many levels of sub-directories to descend into; it is usually set to <code>--max-depth=1</code></p><p>When running, every level of the directory is shown; if you only want to show the current directory, use <code>du -h --max-depth=1 /home/wilson</code></p><h3 id="viewing-files" tabindex="-1">Viewing Files <a class="header-anchor" href="#viewing-files" aria-label="Permalink to &quot;Viewing Files&quot;">​</a></h3><p><code>cat hello.txt</code> view the hello.txt file</p><p><code>cat file1 &gt; file2</code> redirect output</p><p><code>echo wilson &gt;&gt; file1</code> append output</p><p><code>touch a.txt</code> create an empty file a.txt</p><p><code>head -n 10 main.cc</code> view the first 10 lines of main.cc</p><p><code>tail -n 10 main.cc</code> view the last 10 lines of main.cc</p><p><code>wc -l hello.txt</code> view the total number of lines in hello.txt</p><h3 id="searching-file-content" tabindex="-1">Searching File Content <a class="header-anchor" href="#searching-file-content" aria-label="Permalink to &quot;Searching File Content&quot;">​</a></h3><p>grep is a filter that searches for a specified character pattern in files and displays all lines containing that pattern</p><p>The pattern being searched for is called a regular expression</p><p><code>grep hello file1</code> search for hello in file1 and display the line containing hello</p><p>Regular expressions:</p><ul><li><code>^</code>: matches the start, e.g. <code>ls -l|grep ^d</code> shows detailed information of all sub-directories in the current directory</li><li><code>$</code>: matches the end, e.g. <code>ls -l|grep c$</code> shows files in the current directory ending with c</li></ul><p><code>grep -n</code> prepends the line number of the match to the output</p><h2 id="archive-management" tabindex="-1">Archive Management <a class="header-anchor" href="#archive-management" aria-label="Permalink to &quot;Archive Management&quot;">​</a></h2><h3 id="tar-compression-and-packaging" tabindex="-1">tar Compression and Packaging <a class="header-anchor" href="#tar-compression-and-packaging" aria-label="Permalink to &quot;tar Compression and Packaging&quot;">​</a></h3><p>Common parameters:</p><ul><li>c: create a new archive file.</li><li>x: extract files from an archive file.</li><li>f: use the archive file or device.</li><li>v: display the files being processed during archiving.</li><li>z: compress/decompress files with gzip, the suffix is .gz; adding this option compresses the archive file.</li></ul><p>For example: <code>tar czvf source.tar.gz /home/wilson/*</code> compresses all files under the wilson folder</p><h3 id="gzip-decompression" tabindex="-1"><code>gzip</code> Decompression <a class="header-anchor" href="#gzip-decompression" aria-label="Permalink to &quot;`gzip` Decompression&quot;">​</a></h3><p>Common parameters:</p><ul><li>-d: decompress the compressed file.</li><li>-v: display the files being decompressed or compressed during the process.</li></ul><h3 id="scp-remote-copy" tabindex="-1">scp Remote Copy <a class="header-anchor" href="#scp-remote-copy" aria-label="Permalink to &quot;scp Remote Copy&quot;">​</a></h3><p><code>scp filename username@ip:path</code></p><ul><li>filename: the name of the file</li><li>username: the username on the destination host</li><li>ip: the IP of the destination host</li><li>path: the path on the destination host</li></ul><p><code>scp file3 king@192.168.4.52:~/</code> copy from the local machine to another machine</p><p><code>scp king@192.168.4.52:~/file3 .</code> copy from another machine to the local machine</p><p>If you are copying a folder with scp, you need to add <code>-r</code>.</p><h3 id="passwordless-login" tabindex="-1">Passwordless Login <a class="header-anchor" href="#passwordless-login" aria-label="Permalink to &quot;Passwordless Login&quot;">​</a></h3><ul><li><code>ssh-keygen</code> generates a private key and a public key <ul><li>Linux path: ~/.ssh</li><li>Windows path: C:\\Users\\Administrator.ssh</li></ul></li><li><code>ssh-copy-id wilson@192.168.43.142</code> copies the public key to the server&#39;s authorized_keys</li></ul><p>Principle:</p><p><a href="https://ld246.com/article/1640830873031" target="_blank" rel="noreferrer">SSH connection process</a></p><h2 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts&quot;">​</a></h2><p>Ctrl a cursor returns to the beginning of the line</p><p>Ctrl e cursor returns to the end of the line</p>',104)]))}const y=i(d,[["render",c]]);export{g as __pageData,y as default};
